wire_enum! {
    /// Command types the server may send over WS / `GET /agents/{pcId}/commands` (SERVER_API.md
    /// §6.1).
    ServerCommandType {
        /// Lock the session / show idle lock; payload `LockCommand`; result `null`.
        Lock = "lock",
        /// Unlock; no payload; result `null`.
        Unlock = "unlock",
        /// Show an admin message; payload `MessageCommand`; result `MessageDeliveryResult`.
        Message = "message",
        /// Reboot; payload `PowerCommand`; result `ScheduledResult`.
        Reboot = "reboot",
        /// Shut down; payload `PowerCommand`; result `ScheduledResult`.
        Shutdown = "shutdown",
        /// Send a Wake-on-LAN packet to another PC; payload `WakeCommand`; result `null`.
        Wake = "wake",
        /// End the session; payload `EndSessionCommand`; result `SessionResult`.
        EndSession = "endSession",
        /// Extend the session; payload `ExtendSessionCommand`; result `SessionResult`.
        ExtendSession = "extendSession",
        /// Launch a game; payload `LaunchRequest`; result `LaunchResult`.
        LaunchGame = "launchGame",
        /// Kill a game; payload `KillGameCommand`; result `GamesKillResponse`.
        KillGame = "killGame",
        /// Apply a policy; payload `Policy`; result `SetPolicyResult`.
        SetPolicy = "setPolicy",
        /// Re-fetch and apply the policy; no payload; result `ReloadPolicyResult`.
        ReloadPolicy = "reloadPolicy",
        /// Capture the screen; payload `ScreenshotCommand`; result `ScreenshotResult`.
        Screenshot = "screenshot",
        /// Start remote control; payload `RemoteControlStartCommand`; result
        /// `RemoteControlStartResult`.
        RemoteControlStart = "remoteControlStart",
        /// Stop remote control; payload `RemoteControlStopCommand`; result
        /// `RemoteControlStopResult`.
        RemoteControlStop = "remoteControlStop",
        /// Check/apply an update; payload `UpdateCommand`; result `UpdateApplyResponse`.
        Update = "update",
        /// Show ads; payload `ShowAdsArgs`; result `null`.
        ShowAds = "showAds",
        /// Set volume; payload `SetVolumeRequest`; result `VolumeState`.
        SetVolume = "setVolume",
        /// Re-fetch caches; payload `RefreshConfigCommand`; result `RefreshConfigResult`.
        RefreshConfig = "refreshConfig",
    }
}

